// Monta o corpo que a API espera, com os anexos em base64.
//
// O IMAP do n8n entrega os anexos em `binary`, com chaves
// `attachment_0`, `attachment_1`... Cada uma tem `data` (já em base64),
// `mimeType` e `fileName`.
//
// NÃO filtra nada aqui. A triagem — tipo, tamanho, PDF antes de imagem —
// está em `boletoEmail.ts`, com teste. Filtrar nos dois lugares cria
// duas regras que divergem, e a daqui é a que ninguém testa.

const saida = [];

for (const item of $input.all()) {
  const j = item.json;
  const bin = item.binary ?? {};

  const anexos = Object.keys(bin).map((chave) => ({
    nome: bin[chave].fileName ?? chave,
    mime: bin[chave].mimeType ?? 'application/octet-stream',
    base64: bin[chave].data,
  }));

  // E-mail sem anexo nenhum nem chega a ser postado: é propaganda do
  // banco, aviso de privacidade, resposta automática. Uma chamada por
  // e-mail desses seria custo sem nenhuma chance de resultado.
  if (anexos.length === 0) continue;

  saida.push({
    json: {
      // O cabeçalho inteiro, como veio. A API extrai o token dele.
      para: String(j.to ?? ''),
      cc: String(j.cc ?? ''),
      de: String(j.from ?? ''),
      assunto: String(j.subject ?? ''),
      anexos,
    },
  });
}

return saida;
